package br.com.psicomatch.dao;

import br.com.psicomatch.config.Conexao;
import br.com.psicomatch.model.Paciente;
import java.sql.*;
import java.util.*;

public class PacienteDAO implements CrudDAO<Paciente,String> {
    public void inserir(Paciente p)throws Exception{String q="INSERT INTO paciente(paciente_cpf,paciente_nome,paciente_telefone,paciente_endereco,profissional_cpf) VALUES(?,?,?,?,?)";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setString(1,p.getCpf());s.setString(2,p.getNome());s.setString(3,p.getTelefone());s.setString(4,p.getEndereco());if(p.getProfissionalCpf()==null||p.getProfissionalCpf().isBlank())s.setNull(5,Types.VARCHAR);else s.setString(5,p.getProfissionalCpf());s.executeUpdate();}}
    public List<Paciente> listar()throws Exception{List<Paciente> l=new ArrayList<>();try(Connection c=Conexao.conectar();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM paciente ORDER BY paciente_nome")){while(r.next())l.add(map(r));}return l;}
    public Paciente buscar(String cpf)throws Exception{try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement("SELECT * FROM paciente WHERE paciente_cpf=?")){s.setString(1,cpf);try(ResultSet r=s.executeQuery()){return r.next()?map(r):null;}}}
    public void atualizar(Paciente p)throws Exception{String q="UPDATE paciente SET paciente_nome=?,paciente_telefone=?,paciente_endereco=?,profissional_cpf=? WHERE paciente_cpf=?";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setString(1,p.getNome());s.setString(2,p.getTelefone());s.setString(3,p.getEndereco());if(p.getProfissionalCpf()==null||p.getProfissionalCpf().isBlank())s.setNull(4,Types.VARCHAR);else s.setString(4,p.getProfissionalCpf());s.setString(5,p.getCpf());s.executeUpdate();}}
    public void excluir(String cpf)throws Exception{try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement("DELETE FROM paciente WHERE paciente_cpf=?")){s.setString(1,cpf);s.executeUpdate();}}
    public void salvarPreferencias(String cpf,String interesses)throws Exception{try(Connection c=Conexao.conectar()){c.setAutoCommit(false);try(PreparedStatement d=c.prepareStatement("DELETE FROM preferencia_paciente WHERE paciente_cpf=?")){d.setString(1,cpf);d.executeUpdate();}try(PreparedStatement i=c.prepareStatement("INSERT INTO preferencia_paciente(paciente_cpf,interesse) VALUES(?,?)")){for(String item:interesses.split(",")){if(!item.isBlank()){i.setString(1,cpf);i.setString(2,item.trim());i.addBatch();}}i.executeBatch();}c.commit();}}
    public List<String> recomendar(String cpf)throws Exception{String q="SELECT p.profissional_nome,pr.abordagem,pr.especialidades,COUNT(*) pontos FROM preferencia_paciente pp JOIN interesse_profissional ip ON LOWER(pp.interesse)=LOWER(ip.interesse) JOIN profissional p ON p.profissional_cpf=ip.profissional_cpf JOIN perfil_profissional pr ON pr.profissional_cpf=p.profissional_cpf WHERE pp.paciente_cpf=? GROUP BY p.profissional_cpf,p.profissional_nome,pr.abordagem,pr.especialidades ORDER BY pontos DESC";List<String> l=new ArrayList<>();try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setString(1,cpf);try(ResultSet r=s.executeQuery()){while(r.next())l.add(r.getString(1)+" | Abordagem: "+r.getString(2)+" | Especialidades: "+r.getString(3)+" | Afinidades: "+r.getInt(4));}}return l;}
    private Paciente map(ResultSet r)throws SQLException{return new Paciente(r.getString("paciente_cpf"),r.getString("paciente_nome"),r.getString("paciente_telefone"),r.getString("paciente_endereco"),r.getString("profissional_cpf"));}
}
